package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class ForecastSnapshot { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long partnerId; private String horizon; private Double predictedRevenue; private Double confidence; private Instant createdAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getPartnerId(){return partnerId;} public void setPartnerId(Long partnerId){this.partnerId=partnerId;} public String getHorizon(){return horizon;} public void setHorizon(String horizon){this.horizon=horizon;} public Double getPredictedRevenue(){return predictedRevenue;} public void setPredictedRevenue(Double predictedRevenue){this.predictedRevenue=predictedRevenue;} public Double getConfidence(){return confidence;} public void setConfidence(Double confidence){this.confidence=confidence;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} }